 d=CAM/cell['id']; native=[json.loads(l) for l in (d/'native_incremental.jsonl').read_text().splitlines()]; hold=[r for r in native if r['phase']=='hold']; parent=[r for r in native if r['phase']=='parent']; entry=read(d/'hold_entry.json'); outcome=read(d/'outcome.json'); witness=read(d/'witness.json'); before=entry['pre_first_step']; terminal=entry['terminal']; speeds=[math.hypot(r['qvel'][0],r['qvel'][1]) for r in hold]; seed=[math.hypot(r['qvel'][0],r['qvel'][1]) for r in parent[-500:]]
 allspeed=seed+speeds; rolling=[sum(allspeed[i+1:i+501])/500 for i in range(1000)]; xy=[before['qpos'][:2]]+[r['qpos'][:2] for r in hold]; path=sum(math.dist(a,b) for a,b in zip(xy,xy[1:])); net=math.dist(xy[0],xy[-1]); disjoint=[statistics.mean(speeds[:500]),statistics.mean(speeds[500:])]
