 results.append({'cell_id':cell['id'],'status':'PASS' if all(checks.values()) else 'FAIL','checks':checks,'native_steps':len(native),'parent_steps':len(parent),'hold_steps':len(hold),'hold_duration_s':hold[-1]['time_s']-before['time_s'],'first_stop_step':crossing[0],'first_stop_mean_mps':sum(stop[-500:])/500,'first_stop_margin_mps':.1-sum(stop[-500:])/500,'rolling_min_mps':min(rolling),'rolling_max_mps':max(rolling),'rolling_margin_mps':.1-max(rolling),'final_speed_mps':speeds[-1],'instantaneous_max_mps':max(speeds),'disjoint_means_mps':disjoint,'xy_path_length_m':path,'xy_net_displacement_m':net,'min_base_height_m':min(heights),'max_tilt_deg':max(tilts),'historical_native_member_sha256':hashlib.sha256(oldraw).hexdigest()})
